  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "How is domestic GDP defined in this model — is it the total value of all four products produced (steel, engines, electronics, plastic) valued at their world-market prices, or is it only the value of products that are actually exported (i.e., produced minus what is consumed as inputs in other production)?"
  ],
  "rationale": "The response asks for a single policy choice regarding the definition of domestic GDP, presenting two mutually exclusive options for the same variable."
}

{
  "action": "question",
